import React, { useState } from "react";
import {
  Home,
  Users,
  ClipboardList,
  Handshake,
  Clock,
  HandHeart,
  ChevronLeft,
  Search,
  Bell,
  Sun,
  Moon,
} from "lucide-react";

const LOGO_TEAL_ICON = "data:image/png;base64,";
const LOGO_GOLD_ICON = "data:image/png;base64,";

function GenderIcon({ gender, className }) {
  if (gender === "f") {
    return (
      <svg viewBox="0 0 24 24" className={className} fill="currentColor">
        <circle cx="12" cy="6.5" r="4" />
        <path d="M12 10.5 L20.5 22.5 H3.5 Z" />
      </svg>
    );
  }
  return (
    <svg viewBox="0 0 24 24" className={className} fill="currentColor">
      <circle cx="12" cy="6.5" r="4" />
      <path d="M5.5 22.5 V16 a6.5 6.5 0 0 1 13 0 v6.5 Z" />
    </svg>
  );
}


const navItems = [
  { label: "الرئيسية", icon: Home, active: true },
  { label: "المتطوعون", icon: Users, active: false },
  { label: "البرامج", icon: ClipboardList, active: false },
  { label: "الرعاة", icon: Handshake, active: false },
];

const ACCENT_LIGHT = "#1D95A6";
const ACCENT_DARK = "#D6A429";

function getTheme(dark) {
  return {
    sidebarBg: dark ? "bg-[#171A21] border-gray-800" : "bg-gray-100 border-gray-300",
    sidebarBorder: dark ? "border-gray-800" : "border-gray-300",
    card: dark ? "bg-[#171A21] border-gray-800" : "bg-gray-100 border-gray-300",
    textPrimary: dark ? "text-gray-100" : "text-gray-800",
    textSecondary: dark ? "text-gray-500" : "text-gray-400",
    textMuted: dark ? "text-gray-400" : "text-gray-500",
    navInactive: dark ? "text-gray-400 hover:bg-gray-800 hover:text-gray-200" : "text-gray-500 hover:bg-gray-200/70 hover:text-gray-700",
    userStrip: dark ? "bg-gray-800/60" : "bg-gray-200/70",
    editBtnBase: dark ? "bg-[#171A21] border-gray-800 text-gray-300" : "bg-gray-100 border-gray-300 text-gray-600",
  };
}

function Sidebar({ t, dark }) {
  return (
    <aside className={`hidden md:flex md:w-64 shrink-0 flex-col border-l ${t.sidebarBg}`}>
      <div className={`flex items-center gap-3 px-6 py-6 border-b ${t.sidebarBorder}`}>
        <img
          src={dark ? LOGO_GOLD_ICON : LOGO_TEAL_ICON}
          alt="شعار عين"
          className="h-11 w-11 object-contain shrink-0"
        />
        <div>
          <p className={`font-bold leading-tight ${t.textPrimary}`}>منصة عين</p>
          <p className={`text-xs ${t.textSecondary}`}>فريق العين التطوعي</p>
        </div>
      </div>

      <nav className="flex-1 px-3 py-6 space-y-1">
        {navItems.map((item) => (
          <button
            key={item.label}
            className={`w-full flex items-center gap-3 rounded-xl px-4 py-3 text-sm font-medium transition-colors ${
              item.active ? "ain-accent-bg-soft" : t.navInactive
            }`}
          >
            <item.icon className="h-5 w-5" strokeWidth={2} />
            <span>{item.label}</span>
          </button>
        ))}
      </nav>

      <div className={`px-4 py-4 border-t ${t.sidebarBorder}`}>
        <div className={`flex items-center gap-3 rounded-xl px-3 py-3 ${t.userStrip}`}>
          <div className="ain-accent-solid h-9 w-9 rounded-full flex items-center justify-center font-bold text-sm">
            <GenderIcon gender="m" className="h-4 w-4" />
          </div>
          <div className="leading-tight">
            <p className={`text-sm font-semibold ${t.textPrimary}`}>عبدالله فالح</p>
            <p className={`text-xs ${t.textSecondary}`}>مدير النظام</p>
          </div>
        </div>
      </div>
    </aside>
  );
}

function TopBar({ t, dark, setDark }) {
  return (
    <div className="flex items-center justify-between mb-8">
      <div>
        <h1 className={`text-2xl font-bold ${t.textPrimary}`}>مرحبًا بك في منصة عين</h1>
        <p className={`text-sm mt-1 ${t.textSecondary}`}>
          منصة إدارة المتطوعين والبرامج للفريق التطوعي.
        </p>
      </div>
      <div className="hidden sm:flex items-center gap-3">
        <button
          onClick={() => setDark((d) => !d)}
          className={`ain-accent-hover flex items-center gap-2 rounded-full px-3 py-1.5 text-xs font-medium border transition-colors ${t.editBtnBase}`}
        >
          {dark ? <Sun className="h-3.5 w-3.5" /> : <Moon className="h-3.5 w-3.5" />}
          {dark ? "الوضع النهاري" : "الوضع الليلي"}
        </button>
        <button className={`ain-accent-hover h-10 w-10 rounded-full border flex items-center justify-center transition-colors ${t.editBtnBase}`}>
          <Search className="h-4 w-4" />
        </button>
        <button className={`ain-accent-hover h-10 w-10 rounded-full border flex items-center justify-center relative transition-colors ${t.editBtnBase}`}>
          <Bell className="h-4 w-4" />
          <span className="ain-accent-solid absolute -top-0.5 -left-0.5 h-2.5 w-2.5 rounded-full border-2 border-white" />
        </button>
        <div className="ain-accent-solid h-10 w-10 rounded-full flex items-center justify-center font-bold text-sm">
          <GenderIcon gender="m" className="h-4 w-4" />
        </div>
      </div>
    </div>
  );
}

function StatCard({ label, value, suffix, icon: Icon, t }) {
  return (
    <div className={`rounded-2xl border p-5 flex items-center gap-4 ${t.card}`}>
      <div className="ain-accent-bg-soft h-11 w-11 rounded-xl flex items-center justify-center shrink-0">
        <Icon className="h-5 w-5" strokeWidth={2} />
      </div>
      <div>
        <p className={`text-xl font-bold leading-none ${t.textPrimary}`}>
          {value}
          {suffix && <span className={`text-sm font-medium mr-1 ${t.textSecondary}`}>{suffix}</span>}
        </p>
        <p className={`text-xs mt-1.5 ${t.textSecondary}`}>{label}</p>
      </div>
    </div>
  );
}

function ManageCard({ title, icon: Icon, description, t }) {
  return (
    <button className={`ain-accent-hover text-right rounded-2xl border p-6 flex items-start gap-4 transition-all group w-full ${t.card}`}>
      <div className="ain-accent-solid h-12 w-12 rounded-xl flex items-center justify-center shrink-0">
        <Icon className="h-6 w-6" strokeWidth={2} />
      </div>
      <div className="flex-1">
        <p className={`font-bold text-base ${t.textPrimary}`}>{title}</p>
        <p className={`text-sm mt-1 leading-relaxed ${t.textSecondary}`}>{description}</p>
      </div>
      <ChevronLeft className={`h-5 w-5 mt-1 transition-colors ${t.textSecondary}`} />
    </button>
  );
}

export default function App() {
  const [dark, setDark] = useState(false);
  const t = getTheme(dark);
  const accent = dark ? ACCENT_DARK : ACCENT_LIGHT;
  const accentContrast = dark ? "#1A1305" : "#FFFFFF";
  const accentSoft = dark ? "rgba(214,164,41,0.14)" : "rgba(29,149,166,0.10)";
  const accentBorderSoft = dark ? "rgba(214,164,41,0.45)" : "rgba(29,149,166,0.35)";

  const stats = [
    { label: "إجمالي المتطوعين", value: "20", icon: Users },
    { label: "إجمالي البرامج", value: "5", icon: ClipboardList },
    { label: "إجمالي الساعات التطوعية", value: "1,240", suffix: "ساعة", icon: Clock },
    { label: "إجمالي المستفيدين", value: "2,150", icon: HandHeart },
  ];

  return (
    <div
      dir="rtl"
      className="min-h-screen flex transition-colors duration-300"
      style={{
        fontFamily: "'Tajawal', 'Segoe UI', sans-serif",
        backgroundColor: dark ? "#0F1115" : "#F7F2E7",
      }}
    >
      <style>{`
        .ain-accent-solid { background-color: ${accent}; color: ${accentContrast}; }
        .ain-accent-bg-soft { background-color: ${accentSoft}; color: ${accent}; }
        .ain-accent-text { color: ${accent}; }
        .ain-accent-hover:hover { color: ${accent}; border-color: ${accentBorderSoft}; }
      `}</style>

      <Sidebar t={t} dark={dark} />

      <main className="flex-1 px-6 md:px-10 py-8 max-w-5xl">
        <TopBar t={t} dark={dark} setDark={setDark} />

        <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 mb-10">
          {stats.map((s) => (
            <StatCard key={s.label} {...s} t={t} />
          ))}
        </div>

        <h2 className={`text-sm font-bold mb-4 ${t.textMuted}`}>ماذا تريد أن تدير؟</h2>
        <div className="grid sm:grid-cols-3 gap-4">
          <ManageCard
            title="المتطوعون"
            icon={Users}
            description="إدارة بيانات المتطوعين ومشاركاتهم وساعاتهم التطوعية."
            t={t}
          />
          <ManageCard
            title="البرامج"
            icon={ClipboardList}
            description="إدارة البرامج والمشاركين والمستفيدين."
            t={t}
          />
          <ManageCard
            title="الرعاة"
            icon={Handshake}
            description="إدارة الرعاة وسجل الدعم المالي والعيني."
            t={t}
          />
        </div>
      </main>
    </div>
  );
}
